using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;using System.ComponentModel;using System.Globalization;using System.Runtime.Serialization;
namespace CircuitoStudio {
[DataContract]public enum ResidualKind{[EnumMember] RCCB,[EnumMember] ResidualRelay}
[DataContract]public enum ResidualWaveform{[EnumMember] Unknown,[EnumMember] AC,[EnumMember] A,[EnumMember] F,[EnumMember] B}
[DataContract]public enum ControlSupply{[EnumMember] NotApplicable,[EnumMember] AC,[EnumMember] DC}
[DataContract]public sealed class ResidualRating {
[DataMember]public ResidualKind Kind{get;set;}[DataMember]public string Manufacturer{get;set;}[DataMember]public string Reference{get;set;}[DataMember]public ResidualWaveform Waveform{get;set;}[DataMember]public double VoltageV{get;set;}[DataMember]public double FrequencyHz{get;set;}[DataMember]public PoleLayout Poles{get;set;}[DataMember]public double RatedA{get;set;}[DataMember]public double DeltaMilliA{get;set;}[DataMember]public double ConditionalKA{get;set;}[DataMember]public string RequiredPrimaryConfiguration{get;set;}[DataMember]public string SensorReference{get;set;}[DataMember]public string ActuatorReference{get;set;}[DataMember]public string AccessoryReference{get;set;}[DataMember]public string AssemblyDocument{get;set;}[DataMember]public double ControlVoltageV{get;set;}[DataMember]public ControlSupply ControlSupply{get;set;}[DataMember]public string Source{get;set;}[DataMember]public string DataVersion{get;set;}[DataMember]public string Standard{get;set;}[DataMember]public string Conditions{get;set;}
public ResidualRating(){Manufacturer=Reference=RequiredPrimaryConfiguration=SensorReference=ActuatorReference=AccessoryReference=AssemblyDocument=Source=DataVersion=Standard=Conditions="";}
public ResidualRating Copy(){return (ResidualRating)MemberwiseClone();}
public void Validate(){if(!Enum.IsDefined(typeof(ResidualKind),Kind)||!Enum.IsDefined(typeof(ResidualWaveform),Waveform)||Waveform==ResidualWaveform.Unknown||!Enum.IsDefined(typeof(PoleLayout),Poles)||!Enum.IsDefined(typeof(ControlSupply),ControlSupply))throw new InvalidDataException("Tipo/forma de onda/polos/alimentação inválidos.");foreach(string text in new[]{Manufacturer,Reference,Source,DataVersion,Standard,Conditions})if(String.IsNullOrWhiteSpace(text)||text.Length>2000||text.IndexOf('\0')>=0)throw new InvalidDataException("Informe fabricante, referência, fonte, versão, norma declarada e condições (até 2000 caracteres).");foreach(string text in new[]{RequiredPrimaryConfiguration,SensorReference,ActuatorReference,AccessoryReference,AssemblyDocument})if(text==null||text.Length>2000||text.IndexOf('\0')>=0)throw new InvalidDataException("Referência de conjunto inválida.");Project.Range(VoltageV,1,1e6,"tensão do diferencial");Project.Range(FrequencyHz,1,1000,"frequência do diferencial");Project.Range(RatedA,.001,1e9,"In/sensor do diferencial");Project.Range(DeltaMilliA,.001,1e9,"sensibilidade diferencial mA");Project.Range(ConditionalKA,0,1e9,"capacidade condicional");Project.Range(ControlVoltageV,0,1e6,"alimentação auxiliar");if(ConditionalKA==0){if(RequiredPrimaryConfiguration!="")throw new InvalidDataException("Informe capacidade condicional e configuração da proteção juntas.");}else if(RequiredPrimaryConfiguration.Length!=64||RequiredPrimaryConfiguration.Any(x=>!Uri.IsHexDigit(x))||String.IsNullOrWhiteSpace(AssemblyDocument))throw new InvalidDataException("Capacidade condicional exige configuração exata e documento da associação.");if(Kind==ResidualKind.RCCB&&(SensorReference!=""||ActuatorReference!=""||ControlVoltageV!=0||ControlSupply!=ControlSupply.NotApplicable))throw new InvalidDataException("RCCB integrado não usa os campos de sensor/atuador externo ou alimentação auxiliar do relé.");if(Kind==ResidualKind.ResidualRelay&&((ControlVoltageV==0)!=(ControlSupply==ControlSupply.NotApplicable)))throw new InvalidDataException("Informe tensão e tipo de alimentação auxiliar juntos.");}
}
[DataContract]public sealed class ResidualBinding {
[DataMember]public string Engine{get;set;}[DataMember]public ResidualRating Rating{get;set;}[DataMember]public ResidualWaveform RequiredWaveform{get;set;}[DataMember]public PoleLayout RequiredPoles{get;set;}[DataMember]public double MaximumDeltaMilliA{get;set;}[DataMember]public string RequirementSource{get;set;}[DataMember]public double ControlVoltageV{get;set;}[DataMember]public ControlSupply ControlSupply{get;set;}
public void Validate(){if(Engine!=ResidualSelection.EngineId||Rating==null||!Enum.IsDefined(typeof(ResidualWaveform),RequiredWaveform)||!Enum.IsDefined(typeof(PoleLayout),RequiredPoles)||!Enum.IsDefined(typeof(ControlSupply),ControlSupply))throw new InvalidDataException("Seleção diferencial inválida ou revisão desconhecida.");Rating.Validate();Project.Range(MaximumDeltaMilliA,0,1e9,"limite de sensibilidade exigido");Project.Range(ControlVoltageV,0,1e6,"controle do projeto");if(RequirementSource==null||RequirementSource.Length>2000||RequirementSource.IndexOf('\0')>=0||(MaximumDeltaMilliA>0&&String.IsNullOrWhiteSpace(RequirementSource))||(MaximumDeltaMilliA==0&&!String.IsNullOrWhiteSpace(RequirementSource)))throw new InvalidDataException("Informe limite de sensibilidade e referência da regra juntos, ou deixe ambos vazios.");if(Rating.Kind==ResidualKind.RCCB&&(ControlVoltageV!=0||ControlSupply!=ControlSupply.NotApplicable))throw new InvalidDataException("Alimentação auxiliar não se aplica à seleção de RCCB.");if((ControlVoltageV==0)!=(ControlSupply==ControlSupply.NotApplicable))throw new InvalidDataException("Informe tensão e tipo do circuito auxiliar juntos.");}
}
public sealed partial class Circuit{[DataMember(Order=100),Browsable(false)]public ResidualBinding ResidualSelection{get;set;}}
public sealed class ResidualEvaluation{public string Status,Detail;}
public static class ResidualSelection {
public const string EngineId="cs-diferenciais-conjuntos-v1";
public const string Header="Kind;Manufacturer;Reference;Waveform;VoltageV;FrequencyHz;Poles;RatedA;DeltaMilliA;ConditionalKA;RequiredPrimaryConfiguration;SensorReference;ActuatorReference;AccessoryReference;AssemblyDocument;ControlVoltageV;ControlSupply;Source;DataVersion;Standard;Conditions";
public static string PrimaryConfiguration(Circuit c){return Coordination.ProtectionConfiguration(c);}
public static ResidualEvaluation Evaluate(Project p,Study study,Circuit c,ResidualBinding binding){if(binding==null)return new ResidualEvaluation{Status="Pendente",Detail="Diferencial/relé não selecionado."};binding.Validate();var row=study.For(c);if(row==null)throw new InvalidDataException("Circuito fora do projeto.");var r=binding.Rating;bool fail=false,pending=false;var text=new StringBuilder("Motor "+EngineId+". "+(r.Kind==ResidualKind.RCCB?"RCCB":"Relé diferencial")+": "+r.Manufacturer+" / "+r.Reference+"; tipo "+r.Waveform+"; "+r.VoltageV+" V AC; "+r.FrequencyHz+" Hz; "+BreakerSelection.PoleName(r.Poles)+"; In/sensor="+r.RatedA+" A; IΔn="+r.DeltaMilliA+" mA. Fonte: "+r.Source+"; versão "+r.DataVersion+"; norma declarada "+r.Standard+"; condições "+r.Conditions+".\r\n");
Compare(text,"Polos, tensão, frequência e ligação",r.Poles==binding.RequiredPoles&&r.VoltageV==c.Voltage&&r.FrequencyHz==p.Frequency&&BreakerSelection.ValidTopology(row,binding.RequiredPoles),"Condição exata do circuito, sem inferir ligação por proximidade no desenho.",ref fail,ref pending);Compare(text,"Tipo de residual exigido",binding.RequiredWaveform==ResidualWaveform.Unknown?(bool?)null:r.Waveform==binding.RequiredWaveform,"Tipo exigido deve ser escolhido para a forma de onda da aplicação.",ref fail,ref pending);Compare(text,"IΔn ≤ limite do circuito",binding.MaximumDeltaMilliA>0?(bool?)(r.DeltaMilliA<=binding.MaximumDeltaMilliA):null,"Limite="+binding.MaximumDeltaMilliA+" mA; referência da regra: "+binding.RequirementSource+". Nenhuma regra de sensibilidade normativa é deduzida automaticamente.",ref fail,ref pending);Compare(text,"Corrente de carga ≤ In/sensor",row.CurrentA<=r.RatedA,"Ib="+row.CurrentA.ToString("G8",CultureInfo.CurrentCulture)+" A.",ref fail,ref pending);
var primary=c.Protection.BreakerSnapshot;string ignored;bool known=primary!=null&&BreakerSelection.Applicable(p,row,primary,out ignored);Compare(text,"Proteção de sobrecorrente identificada",known?(bool?)(c.BreakerA<=r.RatedA):null,"RCCB/relé não é proteção de sobrecorrente. A proteção primária conserva suas verificações de Ib/In/Iz/I2.",ref fail,ref pending);bool conditional=known&&r.ConditionalKA>0&&String.Equals(r.RequiredPrimaryConfiguration,PrimaryConfiguration(c),StringComparison.OrdinalIgnoreCase);Compare(text,"Associação declarada para curto",conditional&&row.FaultOriginKA.HasValue?(bool?)(r.ConditionalKA>=row.FaultOriginKA.Value&&c.Protection.BreakingCapacityKA>=row.FaultOriginKA.Value):null,"Capacidade condicional="+r.ConditionalKA+" kA; documento: "+r.AssemblyDocument+". Somente a proteção/configuração exata da referência; não equivale a Icu próprio do RCCB/relé.",ref fail,ref pending);
if(r.Kind==ResidualKind.ResidualRelay){Compare(text,"Sensor, atuador e conjunto documentados",!String.IsNullOrWhiteSpace(r.SensorReference)&&!String.IsNullOrWhiteSpace(r.ActuatorReference)&&!String.IsNullOrWhiteSpace(r.AssemblyDocument)?(bool?)true:null,"Sensor="+r.SensorReference+"; atuador="+r.ActuatorReference+"; associação="+r.AssemblyDocument+". O relé sozinho apenas comanda a abertura.",ref fail,ref pending);Compare(text,"Alimentação auxiliar do conjunto",r.ControlVoltageV>0&&binding.ControlVoltageV>0?(bool?)(r.ControlVoltageV==binding.ControlVoltageV&&r.ControlSupply==binding.ControlSupply):null,"Ficha="+r.ControlVoltageV+" V "+r.ControlSupply+"; circuito auxiliar="+binding.ControlVoltageV+" V "+binding.ControlSupply+".",ref fail,ref pending);}if(!String.IsNullOrWhiteSpace(r.AccessoryReference))Compare(text,"Acessório associado",!String.IsNullOrWhiteSpace(r.AssemblyDocument)?(bool?)true:null,"Acessório="+r.AccessoryReference+"; conjunto declarado no documento. Não pressupõe compatibilidade entre fabricantes/modelos.",ref fail,ref pending);
if(new[]{r.Manufacturer,r.Reference,r.Source,r.DataVersion,r.Standard,r.Conditions,r.AssemblyDocument}.Any(x=>x.StartsWith("PREENCHER",StringComparison.OrdinalIgnoreCase))){pending=true;text.AppendLine("Pendente: modelo com campos PREENCHER; não é evidência técnica válida.");}
if(p.GroundingSource!=null&&!Grounding.Complete(p,c)){pending=true;text.AppendLine("Pendente: dados tipados de aterramento/condutores incompletos.");}string earthing=Grounding.EffectiveSystem(p,c).Trim().ToUpperInvariant();if(earthing=="TN-C"){fail=true;text.AppendLine("Não atende: RCD não aplicável ao trecho TN-C com PEN combinado.");}else if(earthing=="TT")Compare(text,"TT: Ra × IΔn ≤ UL",Grounding.Ra(p,c).HasValue?(bool?)(Grounding.Ra(p,c).Value*r.DeltaMilliA/1000<=c.Protection.ContactLimitV):null,"Ra="+Grounding.Ra(p,c)+" Ω; UL="+c.Protection.ContactLimitV+" V. Somente contato; não comprova tempo de eliminação.",ref fail,ref pending);else if(earthing!="TN-S"){pending=true;text.AppendLine("Pendente: esquema/trecho de aterramento não validado para esta seleção; TN-C-S exige identificar separação do PEN e IT exige estudo de faltas próprio.");}if(c.DriveMotor!=null){pending=true;text.AppendLine("Pendente: inversor exige conferir correntes residuais/DC, harmônicos, fugas e instruções específicas do fabricante; o tipo selecionado isoladamente não comprova adequação.");}
text.AppendLine("Avaliação nominal por dados declarados, sem autenticação da associação, seletividade entre diferenciais, tempo máximo de desligamento, condições ambientais ou certificação global. A seleção adicional não altera a sensibilidade/curvas da proteção primária; os resultados de cada dispositivo permanecem separados.");return new ResidualEvaluation{Status=fail?"Não atende":pending?"Dados incompletos":"Atende comparações nominais",Detail=text.ToString()};}
static void Compare(StringBuilder text,string rule,bool? pass,string detail,ref bool fail,ref bool pending){if(!pass.HasValue)pending=true;else if(!pass.Value)fail=true;text.AppendLine((pass.HasValue?(pass.Value?"Atende":"Não atende"):"Pendente")+": "+rule+". "+detail);}
public static void Apply(Project p,Circuit c,ResidualBinding binding){binding.Validate();var result=Evaluate(p,Engineering.Analyze(p),c,binding);if(result.Status=="Não atende")throw new InvalidDataException("Nenhuma alteração: "+result.Detail);c.ResidualSelection=new ResidualBinding{Engine=binding.Engine,Rating=binding.Rating.Copy(),RequiredWaveform=binding.RequiredWaveform,RequiredPoles=binding.RequiredPoles,MaximumDeltaMilliA=binding.MaximumDeltaMilliA,RequirementSource=binding.RequirementSource,ControlVoltageV=binding.ControlVoltageV,ControlSupply=binding.ControlSupply};}
public static ResidualRating Template(Project p,Circuit c,ResidualKind kind){string configuration=PrimaryConfiguration(c);if(configuration=="")throw new InvalidDataException("Selecione uma proteção primária identificada antes de exportar este modelo.");return new ResidualRating{Kind=kind,Manufacturer="PREENCHER fabricante",Reference="PREENCHER referência",Waveform=ResidualWaveform.A,VoltageV=c.Voltage,FrequencyHz=p.Frequency,Poles=c.Protection.BreakerSnapshot.RequiredPoles,RatedA=Math.Max(1,c.BreakerA),DeltaMilliA=30,ConditionalKA=.001,RequiredPrimaryConfiguration=configuration,SensorReference=kind==ResidualKind.ResidualRelay?"PREENCHER sensor":"",ActuatorReference=kind==ResidualKind.ResidualRelay?"PREENCHER atuador":"",AssemblyDocument="PREENCHER documento da associação e capacidade condicional",Source="PREENCHER fonte",DataVersion="PREENCHER versão",Standard="PREENCHER norma declarada",Conditions="PREENCHER condições; substituir todos os valores de exemplo pela ficha"};}
static string Key(ResidualRating r){return String.Join("\0",new[]{r.Kind.ToString(),r.Manufacturer.Trim(),r.Reference.Trim(),r.Waveform.ToString(),r.Poles.ToString(),r.VoltageV.ToString("R",CultureInfo.InvariantCulture),r.FrequencyHz.ToString("R",CultureInfo.InvariantCulture),r.DeltaMilliA.ToString("R",CultureInfo.InvariantCulture),r.SensorReference.Trim(),r.ActuatorReference.Trim(),r.AccessoryReference.Trim(),r.RatedA.ToString("R",CultureInfo.InvariantCulture),r.RequiredPrimaryConfiguration,r.ControlVoltageV.ToString("R",CultureInfo.InvariantCulture),r.ControlSupply.ToString()});}
public static List<ResidualRating> Import(string file){return ComponentCsv.Import<ResidualRating>(file,Header,r=>r.Validate(),Key);}
public static void Export(IEnumerable<ResidualRating> rows,string file){ComponentCsv.Export(rows,file,Header,r=>r.Validate(),Key);}
}
}
